
"use client";

import { useState } from "react";
import { words, type Word } from "../data/words";

const categories = [
  {
    label: "All words",
    subjects: ["Philosophy", "Psychology", "Sociology", "Literature", "Politics", "Linguistic curiosities"],
  },
  {
    label: "Philosophical & psychological",
    subjects: ["Philosophy", "Psychology"],
  },
  {
    label: "Social class & cultural",
    subjects: ["Sociology"],
  },
  {
    label: "Literary & intellectual",
    subjects: ["Literature"],
  },
  {
    label: "Political & sociological",
    subjects: ["Politics"],
  },
  {
    label: "Foreign expressions",
    subjects: ["Linguistic curiosities"],
  },
];

export default function Home() {
  const [activeCategory, setActiveCategory] = useState("All words");
  const [search, setSearch] = useState("");
  const [selectedWord, setSelectedWord] = useState<Word | null>(null);
  const [savedWords, setSavedWords] = useState<number[]>([]);

  const dailyWord = words.find((word) => word.term === "Aporia") ?? words[0];

  const filteredWords = words.filter((word) => {
    const category = categories.find((item) => item.label === activeCategory);

    const matchesCategory =
      !category || category.subjects.includes(word.category);

    const query = search.toLowerCase();

    const matchesSearch = [
      word.term,
      word.meaning,
      word.nuance,
      word.etymology,
      word.category,
      ...word.synonyms,
    ]
      .join(" ")
      .toLowerCase()
      .includes(query);

    return matchesCategory && matchesSearch;
  });

  function toggleSaved(id: number) {
    setSavedWords((current) =>
      current.includes(id)
        ? current.filter((wordId) => wordId !== id)
        : [...current, id]
    );
  }

  return (
    <main className="min-h-screen bg-[#F8F5EF] text-[#373247]">
      <header className="mx-auto flex max-w-7xl items-center justify-between px-6 py-7 md:px-12">
        <a href="#" className="block">
          <h1 className="font-serif text-3xl tracking-[0.16em]">
            LEXICON.
          </h1>
          <p className="mt-1 text-[9px] uppercase tracking-[0.28em] text-[#968B9D]">
            For the verbally insufferable
          </p>
        </a>

        <nav className="hidden items-center gap-9 text-xs md:flex">
          <a href="#today" className="hover:text-[#A28BB7]">
            Daily word
          </a>
          <a href="#library" className="hover:text-[#A28BB7]">
            Library
          </a>
          <a href="#collection" className="hover:text-[#A28BB7]">
            My collection
          </a>
        </nav>

        <button className="rounded-full border border-[#DCD3E0] px-5 py-2 text-xs hover:bg-[#EEE8F2]">
          Sign in
        </button>
      </header>

      <section className="mx-auto max-w-7xl px-6 pb-14 pt-16 md:px-12 md:pt-24">
        <p className="mb-5 text-[10px] uppercase tracking-[0.3em] text-[#A18BAF]">
          EST. 2026 · AN EXERCISE IN ERUDITION
        </p>

        <h2 className="font-serif text-5xl leading-[1.12] md:text-7xl">
          A little pretension
          <br />
          <span className="italic text-[#A18BAF]">
            never hurt.
          </span>
        </h2>
      </section>

      <section className="mx-auto grid max-w-7xl gap-6 px-6 pb-20 md:grid-cols-[1.5fr_1fr] md:px-12">
        <article
          id="today"
          className="border border-[#E8DFE6] bg-[#F0EAF3] p-8 md:p-12"
        >
          <div className="flex items-center justify-between">
            <span className="text-[10px] uppercase tracking-[0.25em] text-[#95839E]">
              The daily word · No. 001
            </span>
            <span className="text-xs text-[#A18BAF]">✳</span>
          </div>

          <p className="mt-14 text-[10px] uppercase tracking-[0.25em] text-[#95839E]">
            {dailyWord.partOfSpeech}
          </p>

          <h3 className="mt-2 font-serif text-6xl md:text-7xl">
            {dailyWord.term}
          </h3>

          <p className="mt-3 text-sm italic text-[#95839E]">
            {dailyWord.pronunciation}
          </p>

          <div className="my-8 h-px bg-[#DCD0E0]" />

          <p className="max-w-xl font-serif text-xl leading-9">
            {dailyWord.meaning}
          </p>

          <p className="mt-5 text-xs text-[#95839E]">
            {dailyWord.etymology}
          </p>

          <div className="mt-9 bg-[#F8F5EF]/70 p-5">
            <p className="mb-2 text-[9px] uppercase tracking-[0.2em] text-[#A18BAF]">
              In a sentence
            </p>
            <p className="font-serif text-sm italic leading-7 text-[#655D6D]">
              “{dailyWord.example}”
            </p>
          </div>

          <button
            onClick={() => toggleSaved(dailyWord.id)}
            className="mt-8 border border-[#BDAEC7] px-5 py-3 text-xs transition hover:bg-[#E7DEEB]"
          >
            {savedWords.includes(dailyWord.id)
              ? "✓ Saved to collection"
              : "+ Save this word"}
          </button>
        </article>

        <aside className="flex flex-col justify-between gap-6">
          <div className="border border-[#E8DFE6] bg-[#EAF0E8] p-8">
            <p className="text-[10px] uppercase tracking-[0.23em] text-[#81927F]">
              Your little obsession
            </p>

            <div className="mt-10 grid grid-cols-2 gap-4">
              <div>
                <p className="font-serif text-4xl">
                  {savedWords.length.toString().padStart(2, "0")}
                </p>
                <p className="mt-1 text-[10px] uppercase tracking-widest text-[#81927F]">
                  Words saved
                </p>
              </div>

              <div>
                <p className="font-serif text-4xl">00</p>
                <p className="mt-1 text-[10px] uppercase tracking-widest text-[#81927F]">
                  Day streak
                </p>
              </div>
            </div>
          </div>

          <div className="border border-[#E8DFE6] bg-[#F6EDE9] p-8">
            <p className="text-[10px] uppercase tracking-[0.23em] text-[#A88981]">
              A little knowledge
            </p>
            <p className="mt-6 font-serif text-5xl">
              {words.length.toString().padStart(2, "0")}
            </p>
            <p className="mt-2 text-xs text-[#887C7B]">
              Words currently in the lexicon.
            </p>
          </div>
        </aside>
      </section>

      <section
        id="library"
        className="border-t border-[#E8DFE6] bg-[#F4F0EA]"
      >
        <div className="mx-auto max-w-7xl px-6 py-16 md:px-12">
          <p className="text-[10px] uppercase tracking-[0.25em] text-[#A18BAF]">
            The intellectual pantry
          </p>

          <h2 className="mt-4 font-serif text-4xl md:text-5xl">
            The vocabulary library.
          </h2>

          <p className="mt-4 text-sm text-[#827B88]">
            Browse, discover and collect words worth keeping.
          </p>

          <div className="mt-9 max-w-xl">
            <input
              type="search"
              value={search}
              onChange={(event) => setSearch(event.target.value)}
              placeholder="Search words, meanings or synonyms..."
              className="w-full border border-[#DED7D8] bg-[#F8F5EF] px-5 py-4 text-sm outline-none transition placeholder:text-[#AAA0AA] focus:border-[#A18BAF]"
            />
          </div>

          <div className="mt-7 flex flex-wrap gap-3">
            {categories.map((category) => (
              <button
                key={category.label}
                onClick={() => {
                  setActiveCategory(category.label);
                  setSelectedWord(null);
                }}
                className={`border px-4 py-3 text-xs transition ${
                  activeCategory === category.label
                    ? "border-[#A18BAF] bg-[#EAE2EE] text-[#65566F]"
                    : "border-[#DED7D8] text-[#827B88] hover:bg-white/60"
                }`}
              >
                {category.label}
              </button>
            ))}
          </div>

          <div className="mt-10 flex items-center justify-between">
            <p className="text-[10px] uppercase tracking-[0.2em] text-[#95839E]">
              {activeCategory}
            </p>
            <p className="text-xs text-[#95839E]">
              {filteredWords.length} entries
            </p>
          </div>

          <div className="mt-5 grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {filteredWords.map((word) => (
              <button
                key={word.id}
                onClick={() => setSelectedWord(word)}
                className="border border-[#E5DDE2] bg-[#F8F5EF] p-6 text-left transition hover:-translate-y-1 hover:border-[#BDAEC7]"
              >
                <div className="flex items-start justify-between gap-2">
                  <span className="text-[9px] uppercase tracking-[0.18em] text-[#A18BAF]">
                    {word.category}
                  </span>
                  <span className="text-[9px] text-[#A18BAF]">
                    {word.difficulty}
                  </span>
                </div>

                <h3 className="mt-5 font-serif text-3xl">
                  {word.term}
                </h3>

                <p className="mt-2 text-xs italic text-[#95839E]">
                  {word.pronunciation}
                </p>

                <p className="mt-5 line-clamp-3 text-sm leading-6 text-[#827B88]">
                  {word.meaning}
                </p>

                <p className="mt-6 text-[10px] uppercase tracking-widest text-[#A18BAF]">
                  Read entry →
                </p>
              </button>
            ))}
          </div>

          {filteredWords.length === 0 && (
            <div className="mt-8 border border-dashed border-[#DCD3E0] p-10 text-center">
              <p className="font-serif text-2xl">
                Nothing found.
              </p>
              <p className="mt-3 text-sm text-[#827B88]">
                Try another word or category.
              </p>
            </div>
          )}

          {selectedWord && (
            <article className="mt-10 border border-[#DCD3E0] bg-[#F0EAF3] p-8 md:p-12">
              <div className="flex items-center justify-between">
                <span className="text-[10px] uppercase tracking-[0.2em] text-[#95839E]">
                  {selectedWord.category} · {selectedWord.difficulty}
                </span>

                <button
                  onClick={() => setSelectedWord(null)}
                  className="text-xs text-[#95839E] hover:text-[#65566F]"
                >
                  Close ✕
                </button>
              </div>

              <h3 className="mt-8 font-serif text-5xl">
                {selectedWord.term}
              </h3>

              <p className="mt-3 text-sm italic text-[#95839E]">
                {selectedWord.pronunciation} · {selectedWord.partOfSpeech}
              </p>

              <div className="my-7 h-px bg-[#DCD0E0]" />

              <p className="font-serif text-xl leading-9">
                {selectedWord.meaning}
              </p>

              <h4 className="mt-8 text-[10px] uppercase tracking-[0.2em] text-[#A18BAF]">
                The nuance
              </h4>
              <p className="mt-3 text-sm leading-7 text-[#655D6D]">
                {selectedWord.nuance}
              </p>

              <h4 className="mt-7 text-[10px] uppercase tracking-[0.2em] text-[#A18BAF]">
                Etymology
              </h4>
              <p className="mt-3 text-sm leading-7 text-[#655D6D]">
                {selectedWord.etymology}
              </p>

              <h4 className="mt-7 text-[10px] uppercase tracking-[0.2em] text-[#A18BAF]">
                In context
              </h4>
              <p className="mt-3 font-serif text-base italic leading-8 text-[#655D6D]">
                “{selectedWord.example}”
              </p>

              <div className="mt-7 grid gap-6 sm:grid-cols-2">
                <div>
                  <h4 className="text-[10px] uppercase tracking-[0.2em] text-[#A18BAF]">
                    Synonyms
                  </h4>
                  <p className="mt-3 text-sm leading-7">
                    {selectedWord.synonyms.join(" · ")}
                  </p>
                </div>

                <div>
                  <h4 className="text-[10px] uppercase tracking-[0.2em] text-[#A18BAF]">
                    Antonyms
                  </h4>
                  <p className="mt-3 text-sm leading-7">
                    {selectedWord.antonyms.join(" · ")}
                  </p>
                </div>
              </div>

              <button
                onClick={() => toggleSaved(selectedWord.id)}
                className="mt-9 border border-[#BDAEC7] px-5 py-3 text-xs transition hover:bg-[#E7DEEB]"
              >
                {savedWords.includes(selectedWord.id)
                  ? "✓ Saved to collection"
                  : "+ Save this word"}
              </button>
            </article>
          )}
        </div>
      </section>

      <footer
        id="collection"
        className="mx-auto max-w-7xl px-6 py-10 md:px-12"
      >
        <div className="flex flex-col justify-between gap-4 border-t border-[#E8DFE6] pt-7 md:flex-row">
          <p className="font-serif text-lg tracking-[0.15em]">
            LEXICON.
          </p>

          <p className="text-[10px] uppercase tracking-[0.2em] text-[#A49AA6]">
            A little pretension never hurt. · 2026
          </p>
        </div>
      </footer>
    </main>
  );
}
